SELECT cm.chat_room_id AS roomId , COUNT(*) AS unreadCount FROM chat_message cm INNER JOIN chat_room_user cru ON cru.chat_room_id = cm.chat_room_id AND cru.user_id = #{userId} WHERE cm.chat_room_id IN
#{roomId}
AND cm.chat_message_id >= cru.unread_start_message_id GROUP BY cm.chat_room_id
